<?php
declare(strict_types=1);
require __DIR__ . '/includes/db.php';
function cl_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function cl_rank(int $published,int $views):array{
 if($published>=20||$views>=50000)return ['Tác giả tiêu biểu','featured','✦'];
 if($published>=10||$views>=10000)return ['Tác giả chính thức','official','◆'];
 if($published>=3||$views>=2000)return ['Cây bút triển vọng','rising','✍'];
 return ['CTV mới','new','✧'];
}
$sql="SELECT m.id,m.display_name,COUNT(CASE WHEN s.status='published' THEN 1 END) published_count,COALESCE(SUM(CASE WHEN s.status='published' THEN s.views_count ELSE 0 END),0) views_count,COALESCE(SUM(CASE WHEN s.status='published' THEN s.likes_count ELSE 0 END),0) likes_count FROM members m LEFT JOIN stories s ON s.member_id=m.id WHERE m.account_type='contributor' AND m.is_active=1 GROUP BY m.id,m.display_name HAVING published_count>0 ORDER BY published_count DESC,views_count DESC,likes_count DESC,m.id ASC LIMIT 30";
$q=$pdo->query($sql);$leaders=$q?$q->fetchAll():[];
$myId=(int)($_SESSION['member_id']??0);$myRank=null;
if($myId){$q=$pdo->prepare("SELECT COUNT(*) published_count,COALESCE(SUM(CASE WHEN status='published' THEN views_count ELSE 0 END),0) views_count FROM stories WHERE member_id=?");$q->execute([$myId]);$mine=$q->fetch()?:[];$myRank=cl_rank((int)($mine['published_count']??0),(int)($mine['views_count']??0));}
