.cl-main{max-width:1000px;margin:auto;padding:25px 16px 75px;color:#eee8f5}.cl-hero{padding:25px;border:1px solid #40304f;border-radius:18px;background:radial-gradient(circle at 85% 15%,#65427a55,transparent 35%),linear-gradient(135deg,#241a31,#11121d)}.cl-kicker{color:#c9a8e7;font-size:.7rem;font-weight:800;letter-spacing:.16em}.cl-hero h1{margin:8px 0;font-size:clamp(1.6rem,5vw,2.3rem)}.cl-hero p{margin:0;color:#b5a9c0;line-height:1.6}.cl-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:17px}.cl-actions a{padding:10px 13px;border:1px solid #58436d;border-radius:10px;background:#332340;color:#f1e5fb;text-decoration:none;font-size:.82rem;font-weight:750}.cl-ranks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:17px 0}.cl-rank{padding:14px;border:1px solid #382e45;border-radius:12px;background:#171520;min-width:0}.cl-rank b{display:block;color:#e9d5fa;font-size:.85rem}.cl-rank small{display:block;margin-top:6px;color:#a99fb4;font-size:.72rem;line-height:1.5}.cl-panel{padding:17px;border:1px solid #352c41;border-radius:15px;background:#12121b}.cl-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:13px}.cl-head h2{margin:0;font-size:1.05rem}.cl-head small{color:#a99fb4;font-size:.73rem}.cl-list{display:grid;gap:9px}.cl-item{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px;border:1px solid #302a3d;border-radius:11px;background:#191722;min-width:0}.cl-number{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:#2c2438;color:#e8d4fa;font-weight:900}.cl-item:nth-child(1) .cl-number{background:#594322;color:#ffe2a0}.cl-item:nth-child(2) .cl-number{background:#3b414b;color:#e2e8f2}.cl-item:nth-child(3) .cl-number{background:#50372d;color:#f4c4a6}.cl-info{min-width:0}.cl-info strong{display:block;overflow-wrap:anywhere;color:#f0e9f7;font-size:.9rem}.cl-info small{display:block;margin-top:5px;color:#a99fb4;font-size:.72rem;line-height:1.45}.cl-rank-tag{white-space:nowrap;padding:6px 9px;border-radius:30px;font-size:.68rem;font-weight:800}.cl-rank-tag.new{background:#292638;color:#d6c7e9}.cl-rank-tag.rising{background:#263a36;color:#bde9d6}.cl-rank-tag.official{background:#302c49;color:#d6c7ff}.cl-rank-tag.featured{background:#49351f;color:#ffe0a4}.cl-empty{padding:25px;text-align:center;border:1px dashed #44384f;border-radius:11px;color:#a99fb4}.cl-note{margin:13px 0 0;color:#82798e;font-size:.72rem;line-height:1.6}
